--
-- Name: is_account_absent(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: zivver
--

CREATE FUNCTION public.is_account_absent(ts timestamp with time zone, account_id integer) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  dt_today timestamp with time zone;
  dt_yesterday timestamp with time zone;
BEGIN

  SELECT timezone(
    case when (select p.timezone in (select name from pg_timezone_names))
      then p.timezone
      else 'UTC' end, ts)
    INTO dt_today
    FROM profiles p
    WHERE p.id = account_id;

  dt_yesterday := dt_today - interval '1 day';

  return EXISTS(
    SELECT 1
    FROM account_scheduled_absences AS s
    WHERE s.registered_account_id = account_id
      AND (dt_today BETWEEN s.start_ts AND s.end_ts)
      AND (
        (s.is_recurring AND (s.start_ts::time <= s.end_ts::time))
          AND (s.dow = '{}' OR date_part('isodow', dt_today) = ANY (s.dow))
          AND (s.dom = '{}' OR date_part('day', dt_today) = ANY (s.dom))
          AND (s.moy = '{}' OR date_part('month', dt_today) = ANY (s.moy))
          AND (dt_today::time BETWEEN s.start_ts::time AND s.end_ts::time)
        OR
        (s.is_recurring AND (s.start_ts::time > s.end_ts::time))
          AND (s.dow = '{}' OR date_part('isodow', dt_today) = ANY (s.dow))
          AND (s.dom = '{}' OR date_part('day', dt_today) = ANY (s.dom))
          AND (s.moy = '{}' OR date_part('month', dt_today) = ANY (s.moy))
          AND (dt_today::time >= s.start_ts::time)
        OR
        (s.is_recurring AND (s.start_ts::time > s.end_ts::time))
          AND (s.dow = '{}' OR date_part('isodow', dt_yesterday) = ANY (s.dow))
          AND (s.dom = '{}' OR date_part('day', dt_yesterday) = ANY (s.dom))
          AND (s.moy = '{}' OR date_part('month', dt_yesterday) = ANY (s.moy))
          AND (dt_today::time < s.end_ts::time)
        OR
          NOT s.is_recurring
      )
    LIMIT 1
  );
END;
$$;


